document.addEventListener('click',e=>{const el=e.target.closest('button,a,[data-event]');if(!el)return;if(el.dataset.route){e.preventDefault();go(el.dataset.route);return}if(el.dataset.action){const f=actions[el.dataset.action];if(f){e.preventDefault();f()}return}if(el.dataset.tab){setTab(el.dataset.tab,el.dataset.value);return}if(el.dataset.well){if(state.workflowRunning){notify('流程已冻结对象，重置后切换井。');return}Object.assign(state,switchWellState(state,el.dataset.well));state.wellTab='daily';paint();return}if(el.dataset.model){state.modelId=el.dataset.model;paint();return}if(el.dataset.event!==undefined){state.eventIndex=Number(el.dataset.event);paint();return}if(el.dataset.feature){const f=D.requirements.features.find(f=>f.id===el.dataset.feature);if(f)featureRoute(f);return}if(el.dataset.placeholder){modal(el.dataset.placeholder,`${chip('仅入口','amber')}<p style="margin-top:15px">按本次范围仅保留按钮，未执行此项业务。可在“PPT功能全景”查看对应技术方案位置。</p>`);return}if(el.dataset.catalog){const c=D.requirements.data_catalog.find(c=>c.code===el.dataset.catalog);modal(c.display_name,`${chip(c.code+' · 目录入口','blue')}<p style="margin-top:12px">${esc(c.category)}，来源PPT第12页。</p><p style="margin-top:12px">本次不实现该完整专业数据库；实际可用样本请进入数据质控、单井视图或模型实验室。</p>`);return}if(el.dataset.page!==undefined){state.cataloguePage=Number(el.dataset.page);paint();return}if(el.dataset.doc){const d=D.docs.find(d=>d.doc_id===el.dataset.doc);modal('原文事实与标注依据',`<p>${esc(d.text)}</p><div class="divider"></div><pre class="code-block">${esc(JSON.stringify(d,null,2))}</pre>`);return}if(el.dataset.flowNode){state.workflowNode=el.dataset.flowNode;$('#flow-node-detail').innerHTML=flowNodeDetails(state.workflowNode)}});
document.addEventListener('change',async e=>{const t=e.target;switch(t.id){case'analysis-object':state.objectScope=t.value;state.eventIndex=0;paint();break;case'grin-window':state.grinForecast=null;state.grinForecastError='';state.grinWindow=Number(t.value);state.qualityRun=false;state.qualityResult=null;paint();break;case'grin-well':state.grinForecast=null;state.grinForecastError='';state.grinWell=t.value;state.qualityRun=false;state.qualityResult=null;paint();break;case'grin-feature':state.grinForecast=null;state.grinForecastError='';state.grinFeature=Number(t.value);state.qualityRun=false;state.qualityResult=null;paint();break;case'grin-forecast-horizon':state.grinForecastHorizon=Number(t.value);state.grinForecast=null;state.grinForecastError='';paint();break;case'lag-injector':state.lagInjector=t.value;state.lagResult=null;paint();break;case'lag-target':state.lagTarget=t.value;state.lagResult=null;paint();break;case'lag-max':state.lagMax=Number(t.value);state.lagResult=null;paint();break;case'global-well':if(state.workflowRunning){t.value=state.well;return notify('流程运行中已冻结对象；重置流程后可切换井。')}Object.assign(state,switchWellState(state,t.value));state.mechanismDate=null;paint();break;case'quality-dataset':state.qualityData=t.value;state.qualityRun=false;state.qualityResult=null;paint();break;case'graph-source':state.graphFocusedEdge=null;state.graphSource=t.value;state.graphQuery=t.value==='FORCE'?'15/9-13':t.value==='OPM'?'SPE9':t.value==='Volve'?currentWell().name:'';paint();break;case'extract-doc':state.docIndex=Number(t.value);state.uieRun=false;paint();break;case'rotate-head':state.rotateHead=t.value;state.rotateResults=null;paint();break;case'rotate-relation':state.rotateRelation=t.value;state.rotateResults=null;paint();break;case'time-range':state.range=Number(t.value);paint();break;case'crm-source':state.crmSource=t.value;paint();break;case'arps-source':state.arpsSource=t.value;state.mechanismDate=null;state.arpsResult=null;paint();break;case'arps-case':state.arpsCase=Number(t.value);state.arpsResult=null;paint();break;case'stable-confirm':state.stableConfirmed=t.checked;break;case'workflow-fault':state.workflowFault=t.checked;break;case'simulation-case':state.simCase=Number(t.value);state.simResult=null;state.simSnapshot=0;state.simAperture=D.physics.cases[state.simCase].parameters.reference_aperture_mm;state.simPressure=D.physics.cases[state.simCase].parameters.pressure_drop_mpa;paint();break;case'catalogue-module':state.catalogueModule=t.value;paint();break;case'catalogue-status':state.catalogueFilter=t.value;paint();break;case'csv-upload':if(t.files[0]){try{const rows=parseCSV(await t.files[0].text());if(rows.length>50000)throw Error('单次演示导入最多50,000行');state.uploadedRows=rows;state.qualityData='uploaded';state.qualityRun=false;state.qualityResult=null;paint();notify('已在当前浏览器内载入'+num(rows.length)+'条CSV记录。')}catch(err){notify('导入失败：'+err.message)}}break}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='simulation-time'){state.simSnapshot=Number(t.value);updateSimTime()}for(const[id,key,suffix]of[['sim-aperture','simAperture',' mm'],['sim-pressure','simPressure',' MPa'],['sim-duration','simDuration',' d'],['arps-horizon','arpsHorizon',' d']])if(t.id===id){state[key]=Number(t.value);t.parentElement.querySelector('output').textContent=num(state[key],id==='sim-duration'||id==='arps-horizon'?0:1)+suffix}if(t.id==='catalogue-search'){state.catalogueSearch=t.value;clearTimeout(pendingTimer);const caret=t.selectionStart;pendingTimer=setTimeout(()=>{paint();const el=$('#catalogue-search');el.focus();el.setSelectionRange(caret,caret)},220)}});
