async function boot(){try{const files={trainingContracts:'training-contracts.json',verification:'service-verification.json',summary:'summary.json',master:'master.json',productionRaw:'production.json',requirements:'requirements.json',graph:'graph.json',docs:'documents.json',events:'events.json',logs:'well-logs.json',jointQc:'joint-qc.json',arps:'arps-benchmarks.json',physics:'physics-assets.json',physicsInput:'physics-runtime-input.json',realCrm:'real-crm.json',models:'models/model-assets.json',forest:'models/isolation_forest_browser.json',rotate:'models/rotate_browser.json',grinExamples:'models/grin_examples.json',anomalyExamples:'models/anomaly_transformer_examples.json',uieRaw:'models/uie_test_predictions.json',datasetExamples:'models/dataset_examples.json'};const entries=await Promise.all(Object.entries(files).map(async([key,path])=>[key,await load(path)]));D=Object.fromEntries(entries);setupStudio({models:D.trainingContracts.models,refresh:paint,notify,verificationData:D.verification});D.production=D.productionRaw.rows.map(row=>Object.fromEntries(D.productionRaw.columns.map((c,i)=>[c,row[i]])));const groups=new Map();for(const p of D.uieRaw){let g=groups.get(p.doc_id);if(!g){g={doc_id:p.doc_id,content:p.content,predictions:[]};groups.set(p.doc_id,g)}g.predictions.push(p)}D.uieExamples={examples:[...groups.values()]};state.well=D.master.wells.find(w=>w.name==='15/9-F-14')?.id??D.master.wells[0].id;state.simSnapshot=simCurrent().snapshots.length-1;observeUnitNotes(document.body);paint();window.__GEOTWIN__={state,data:D,actions,refresh:paint,version:'2026.10'};}catch(e){console.error(e);root.innerHTML=`<div class="boot"><strong>ChinaOil <span>GeoTwin</span></strong><p>研究数据尚未准备完成</p><small>${esc(e.message)}</small><button class="btn" id="retry-boot">重新载入</button></div>`;$('#retry-boot').addEventListener('click',boot)}}
boot();
const GRIN_FEATURE_LABELS={oil_volume_sm3:'产油体积',water_volume_sm3:'产水体积',water_injection_volume_sm3:'注水体积',pressure_for_model_source_unit:'井压（源单位未核定）'};
function getGrinView(){const ex=D.grinExamples[state.grinWindow??0],well=ex.well_ids.includes(state.grinWell??state.well)?state.grinWell??state.well:ex.well_ids[0];return grinCompletion(ex,well,state.grinFeature??1)}
function qualityImpute(){const ex=D.grinExamples[state.grinWindow??0],view=getGrinView(),m=model('grin'),ran=state.qualityRun,windowNote=describeGrinWindow(ex),unit=view.feature==='pressure_for_model_source_unit'?'源单位未核定':'Sm3/d（标准立方米/日）',rows=view.rows.map(r=>({...r,prediction:ran?r.prediction:null,output_value:ran?r.output_value:r.input_value,status:ran?r.status:r.input_value===null?'缺失 · 待补全':'原观测保留'}));return header('DATA GOVERNANCE / GRAPH IMPUTATION','多源数据清洗与联合质控','GRIN重建缺失数据，再接因果自回归预测头，展示历史与未来的独立区间。',btn('下载补全结果 CSV','export-grin-csv',{ic:'download'}))+`<div class="tabs">${[['detect','异常检测'],['impute','缺失补全'],['rules','专业联合质控']].map(([id,t])=>`<button class="${state.qualityTab===id?'active':''}" data-tab="qualityTab" data-value="${id}">${t}</button>`).join('')}</div><div class="model-banner"><div><b>GRIN · 图循环插补网络（精简结构复现）</b><p>内置Volve窗口使用已训练GRIN的真实冻结预测，点击后生成补全候选数据。自有数据可进入模型训练与计算中心，连接训练服务计算。</p></div><div class="compact-links">${btn('补全数据并显示预测结果','run-quality',{primary:true,ic:'play'})}${btn('补全后进行时序预测','run-grin-forecast',{ic:'activity'})}${btn('上传自有数据并计算','grin-open-studio',{ic:'upload'})}</div></div><div class="kpi-grid">${kpi('输入缺失',view.missing,'处',ex.dates.length+'条时间记录','database','blue')}${kpi('已补全候选',ran?view.filled:'—','处','短缺口且预测非负 · 待审核','check')}${kpi('待核查 / 不适用',ran?view.pending:'—','处','不将拒绝预测写入补全数据','warning','amber')}${kpi('剩余缺失',ran?view.pending:view.missing,'处','原始观测始终保留','shield','purple')}</div><div class="grid two-col"><div>${panel('补全前后数据与预测结果',`<div class="panel-body"><div class="inline-controls grin-controls"><select id="grin-window" aria-label="GRIN冻结窗口">${D.grinExamples.map((x,i)=>`<option value="${i}" ${i===(state.grinWindow??0)?'selected':''}>${x.window_id} · 测试窗口 · ${x.dates[0]}—${x.dates.at(-1)}</option>`).join('')}</select><select id="grin-well" aria-label="GRIN窗口井">${ex.well_ids.map(w=>`<option value="${w}" ${w===view.well_id?'selected':''}>${D.master.wells.find(x=>x.id===w)?.name??w}</option>`).join('')}</select><select id="grin-feature" aria-label="GRIN插补变量">${ex.feature_names.map((f,i)=>`<option value="${i}" ${i===(state.grinFeature??1)?'selected':''}>${GRIN_FEATURE_LABELS[f]??f}</option>`).join('')}</select></div><div class="grin-window-note"><b>当前测试窗口：${esc(ex.window_id)}</b><p>${esc(windowNote.description)}</p></div><p class="description">当前变量：${esc(GRIN_FEATURE_LABELS[view.feature]??view.feature)} · 单位：${unit}</p><div id="grin-chart"></div>${renderGrinLegend()}<div class="divider"></div>${ran?`<div class="grin-result-summary" role="status">补全处理完成：${view.filled}处形成补全候选，${view.pending}处保留缺失。以下展示全部${rows.length}条记录。</div>`:notice('点击“补全数据并显示预测结果”后，同时显示GRIN预测值与补全后数据。')}<div class="grin-results">${table(rows,[{key:'date',label:'日期'},{key:'input_value',label:'补全前',render:v=>grinCell(v,finite(v)?'observed':'missing')},{key:'prediction',label:'GRIN缺失重建值',render:v=>finite(v)?grinCell(v,v<0?'rejected':'imputed'):'—'},{key:'output_value',label:'补全后（候选）',render:(v,r)=>grinCell(v,r.input_value===null?(finite(v)?'imputed':'missing'):'observed')},{key:'target',label:'遮蔽评估真值',render:v=>finite(v)?grinCell(v,'truth'):'—'},{key:'missing_kind',label:'缺失类型',text:true},{key:'status',label:'质量标记',text:true}],{limit:rows.length})}</div><div class="compact-links section-gap">${btn('下载补全数据 CSV','export-grin-csv',{ic:'download'})}${btn('下载预测与评价 JSON','export-quality',{ic:'download'})}</div>${renderGrinForecastPanel(view,unit)}</div>`,{ic:'database',right:chip('真实模型冻结预测','blue'),note:'历史段由GRIN重建；未来段由独立因果自回归预测头生成。遮蔽真值只用于重建评价，不参与后续预测拟合。'})}</div><div>${panel('本次选择的重建评价',`<div class="panel-body"><div class="stat-row"><span>可评估遮蔽点</span><b>${view.heldout}</b></div><div class="stat-row"><span>MAE · ${unit}</span><b>${ran?num(view.metrics.mae,3):'—'}</b></div><div class="stat-row"><span>RMSE · ${unit}</span><b>${ran?num(view.metrics.rmse,3):'—'}</b></div><p class="description section-gap">仅在有独立遮蔽真值的位置计算误差。天然缺失没有真值，不报告插补准确率。</p><div class="divider"></div>${notice('非负且连续缺口不超过3条的预测进入补全候选；负预测、长缺口及整段无观测字段保留缺失，逐条给出原因。候选需业务复核。',true)}</div>`,{ic:'shield'})}<div class="section-gap">${panel('训练与来源证据',`<div class="panel-body">${splitBar(m.split,'时间记录')}<p class="description section-gap">${esc(m.split.policy)}</p>${modelMetricsCard(m)}<div class="divider"></div><div class="stat-row"><span>窗口</span><b>${esc(view.window_id)}</b></div><div class="stat-row"><span>输入井</span><b>${esc(view.well_id)}</b></div><p class="micro section-gap">内置窗口未重新训练；使用已保存的实际推理输出。任意上传数据的训练、补全与推理请使用独立计算服务。</p>${btn('查看GRIN模型实验','model-quality',{small:true})}</div>`,{ic:'flask'})}</div></div></div>`}
function runGrin(){state.grinForecast=null;state.grinForecastError='';const started=performance.now(),view=getGrinView();state.qualityRun=true;state.qualityResult={...view,run_at:new Date().toISOString(),mode:'frozen_grin_completion',source:'Volve_public_observations_with_controlled_mask',completion_seconds:(performance.now()-started)/1000,flagged:view.pending};paint();notify(`已生成补全结果：${view.filled}处候选，${view.pending}处保留缺失并标记原因。`)}
function exportGrinCsv(){if(!state.qualityRun||state.qualityResult?.mode!=='frozen_grin_completion')return notify('请先补全当前窗口数据');const r=state.qualityResult,headers=['日期','井编码','变量','补全前','GRIN预测值','补全后候选','遮蔽评估真值','缺失类型','质量标记','单位'],unit=r.feature==='pressure_for_model_source_unit'?'源单位未核定':'标准立方米/日',cell=v=>v===null||v===undefined?'':`"${String(v).replaceAll('"','""')}"`,lines=[headers,...r.rows.map(x=>[x.date,x.well_id,GRIN_FEATURE_LABELS[x.feature]??x.feature,x.input_value,x.prediction,x.output_value,x.target,x.missing_kind,x.status,unit])];download('\uFEFF'+lines.map(row=>row.map(cell).join(',')).join('\r\n'),'GRIN-completion-'+r.window_id.replaceAll(':','_')+'.csv')}
function graphPropertyText(properties){const labels={observed_depth_min_m:'最小观测测深（米）',observed_depth_max_m:'最大观测测深（米）'};return Object.entries(properties).map(([k,v])=>esc(labels[k]??k)+'：'+esc(typeof v==='object'?JSON.stringify(v):String(v))).join('；')||'该关系未附加属性；来源见上方数据集标记'}
function currentGraph(){const g=queryGraph(D.graph,state.graphQuery,{source:state.graphSource==='all'?null:state.graphSource,limit:65}),edge=state.graphFocusedEdge;if(edge){const ids=new Set([edge.source_id,edge.target_id]),pinned=D.graph.nodes.filter(n=>ids.has(n.id));g.nodes=[...pinned,...g.nodes.filter(n=>!ids.has(n.id))].slice(0,65);const visible=new Set(g.nodes.map(n=>n.id));g.edges=D.graph.edges.filter(e=>visible.has(e.source_id)&&visible.has(e.target_id))}return g}
function selectGraphEntity(id,edge=null){const node=D.graph.nodes.find(n=>n.id===id);if(!node)return;state.selectedNode=id;const visible=currentGraph();if(!visible.nodes.some(n=>n.id===id)||(edge&&!visible.nodes.some(n=>n.id===edge.target_id))){state.graphSource='all';state.graphQuery=id;state.graphFocusedEdge=edge;paint()}network?.setSelection(id,edge);const select=$('#graph-entity-select');if(select)select.value=id;const rows=entityRelations(D.graph,id),active=edge?rows.find(e=>e.source_id===edge.source_id&&e.target_id===edge.target_id&&e.relation===edge.relation):null;$('#node-inspector').innerHTML=`<div class="flex between wrap"><b>${esc(node.label)}</b>${chip(rows.length+'条直接关系','blue')}</div><p class="mono">${esc(node.id)} · 来源：${esc(node.source??'未注明')}</p><details><summary>实体属性</summary><pre>${esc(JSON.stringify(node.properties??{},null,2))}</pre></details>${active?`<div class="relation-focus" role="status"><b>${esc(active.source.label)} → ${esc(active.relation_label)} → ${esc(active.target.label)}</b><p>关系编码：${esc(active.relation)} · 来源：${esc(active.source_dataset??active.source.source??'未注明')}</p><p>关系属性 / 证据：${graphPropertyText(active.properties??{})}</p></div>`:''}<p>点击下方任一关系，查看有向连线和证据；点击关联实体可继续展开。</p><div class="entity-relation-list">${rows.map(e=>`<div class="entity-relation-row ${active?.index===e.index?'selected':''}"><button data-relation-index="${e.index}" class="relation-select"><span>${esc(e.source.label)}</span><b>→ ${esc(e.relation_label)} →</b><span>${esc(e.target.label)}</span><small>${e.direction==='outgoing'?'本实体指向关联实体':'关联实体指向本实体'} · 来源：${esc(e.source_dataset??e.source.source??'未注明')}</small></button><button class="btn small" data-entity-id="${esc(e.source_id===id?e.target_id:e.source_id)}">展开关联实体</button></div>`).join('')||'<p>当前实体没有可追溯的直接关系。</p>'}</div>`;annotateUnits($('#node-inspector'));}
function selectGraphRelation(edge){selectGraphEntity(edge.source_id,edge)}
document.addEventListener('click',e=>{const entity=e.target.closest('[data-entity-id]'),relation=e.target.closest('[data-relation-index]');if(entity)selectGraphEntity(entity.dataset.entityId);if(relation){const edge=D.graph.edges[Number(relation.dataset.relationIndex)];if(edge)selectGraphRelation(edge)}});
document.addEventListener('change',e=>{if(e.target.id==='graph-entity-select'&&e.target.value)selectGraphEntity(e.target.value)});
function temporalPanel(){const injectors=D.master.wells.filter(w=>w.kind==='injection'),producers=D.master.wells.filter(w=>w.kind==='production'),inj=state.lagInjector??injectors[0].id,target=state.lagTarget??producers.find(w=>w.id===state.well)?.id??producers[0].id,r=state.lagResult;return`<div class="grid two-col">${panel('注采时滞关联分析',`<div class="panel-body"><div class="field-row"><div><label class="form-label">注水井</label><select id="lag-injector" style="width:100%">${injectors.map(w=>`<option value="${w.id}" ${w.id===inj?'selected':''}>${w.name}</option>`).join('')}</select></div><div><label class="form-label">响应采油井</label><select id="lag-target" style="width:100%">${producers.map(w=>`<option value="${w.id}" ${w.id===target?'selected':''}>${w.name}</option>`).join('')}</select></div></div><div class="flex between"><label class="form-label">最大时滞 <select id="lag-max"><option value="30" ${state.lagMax===30?'selected':''}>30天</option><option value="60" ${state.lagMax===60?'selected':''}>60天</option><option value="90" ${state.lagMax===90?'selected':''}>90天</option></select></label>${btn('计算时滞关联','run-lag',{primary:true,ic:'play'})}</div><div id="lag-chart" style="margin-top:12px">${r?'':empty('按日历日期对齐后计算0至最大时滞的相关系数')}</div><div class="divider"></div>${notice('只使用2014-01-01以前的训练期公开观测，日期缺口不补零。时滞相关不代表因果关系或已验证井间连通性。',true)}</div>`,{ic:'activity'})}${panel('时序证据与关联候选',`<div class="panel-body">${r?.best?`<div class="metric-grid">${metric('最高绝对相关时滞',r.best.lag+' d','训练期统计')}${metric('Pearson r',num(r.best.correlation,3),'可正可负，不是置信度')}${metric('有效配对',num(r.best.pairs),'日历对齐观测')}</div><div class="divider"></div>${table([...r.rows].filter(x=>x.correlation!==null).sort((a,b)=>Math.abs(b.correlation)-Math.abs(a.correlation)).slice(0,6),[{key:'lag',label:'时滞 d'},{key:'correlation',label:'相关系数',decimals:4},{key:'pairs',label:'配对记录'}])}`:empty('运行后显示时滞、样本量和统计关联')}<div class="divider"></div><p class="description">可将该统计关联作为图谱的“待验证动态关联”证据，保留井对、时间范围和计算方法；不写入已确认地质连通关系。</p></div>`,{ic:'graph'})}</div>`}
function runLag(){const inj=state.lagInjector??D.master.wells.find(w=>w.kind==='injection').id,target=state.lagTarget??D.master.wells.find(w=>w.id===state.well&&w.kind==='production')?.id??D.master.wells.find(w=>w.kind==='production').id,train=allRows().filter(r=>r.date<'2014-01-01');state.lagResult={...lagCorrelation(train.filter(r=>r.well_id===inj).map(r=>({date:r.date,value:r.water_injection_volume_sm3})),train.filter(r=>r.well_id===target&&r.on_stream_hours>0).map(r=>({date:r.date,value:r.oil_rate_per_onstream_day_sm3})),{maxLag:state.lagMax}),injector:inj,target,source:'public_train_period_calendar_aligned'};paint();notify('已完成训练期实际注采观测的日历时滞关联计算。')}
function analysisObjectSelect(){return`<select id="analysis-object" aria-label="诊断分析对象"><option value="well" ${state.objectScope==='well'?'selected':''}>单井对象</option>${D.master.groups.map((g,i)=>`<option value="group:${i}" ${state.objectScope==='group:'+i?'selected':''}>${g.name} · 生成映射</option>`).join('')}<option value="block" ${state.objectScope==='block'?'selected':''}>区块汇总 · 生成映射</option></select>`}
function analysisWellIds(){if(state.objectScope==='well')return[state.well];if(state.objectScope==='block')return D.master.wells.map(w=>w.id);const g=D.master.groups[Number(state.objectScope.split(':')[1])];return[g.injector,...g.producers]}
function analysisRows(){if(state.objectScope==='well')return recentRows(730);const ids=new Set(analysisWellIds()),rows=allRows().filter(r=>ids.has(r.well_id));const last=Math.max(...rows.map(r=>Date.parse(r.date)));return aggregatePeriod(rows.filter(r=>Date.parse(r.date)>=last-730*864e5),'day')}
function balancePanel(){const ids=new Set(state.objectScope==='well'?D.master.wells.map(w=>w.id):analysisWellIds()),rows=allRows().filter(r=>ids.has(r.well_id)&&r.date>='2015-01-01'),monthly=aggregatePeriod(rows,'month').filter(r=>r.liquid_volume_sm3>0&&r.water_injection_volume_sm3!==null).map(r=>({...r,ratio:r.water_injection_volume_sm3/r.liquid_volume_sm3})),candidates=monthly.filter(r=>r.ratio<.8||r.ratio>1.5);return panel('注采平衡候选筛查',`<div class="panel-body"><div class="flex between wrap"><span class="description">${state.objectScope==='well'?'当前单井无封闭注采边界，展示Volve油田汇总筛查。':'当前演示井组/区块归属下的地面体积筛查。'}</span>${chip('非确诊失衡','amber')}</div><div class="divider"></div>${table(candidates.slice(-4).reverse(),[{key:'date',label:'月份'},{key:'water_injection_volume_sm3',label:'注水 Sm3',decimals:0},{key:'liquid_volume_sm3',label:'产液 Sm3',decimals:0},{key:'ratio',label:'地面注采比',decimals:3}],{limit:4})}<p class="micro" style="margin-top:12px">演示阈值：低于0.8或高于1.5。月汇总可能受记录覆盖影响；必须补充PVT、边界与含水层资料后判断地下体积平衡。</p></div>`,{ic:'layers'})}

function grinSymbol(kind){return{observed:'●',imputed:'■',rejected:'×',truth:'◇',forecast:'▲',missing:'▥'}[kind]??'●'}
function grinCell(value,kind){const m=GRIN_MARKS[kind];return `<span class="grin-value" style="--mark-color:${m.color}" title="${esc(m.label)}"><i aria-hidden="true">${grinSymbol(kind)}</i>${finite(value)?num(Number(value),3):'缺失'}</span>`}
function renderGrinLegend(){return `<div class="grin-legend" aria-label="GRIN数据标记图例">${Object.entries(GRIN_MARKS).map(([kind,m])=>`<span class="grin-legend-item" style="--mark-color:${m.color}"><i aria-hidden="true">${grinSymbol(kind)}</i><span><b>${m.label}</b><small>${m.encoding}</small></span></span>`).join('')}</div>`}
function currentGrinForecast(){const v=getGrinView(),f=state.grinForecast;return state.qualityRun&&f&&f.window_id===v.window_id&&f.well_id===v.well_id&&f.feature===v.feature&&f.horizon===(state.grinForecastHorizon??7)?f:null}
function renderGrinForecastPanel(view,unit){const f=currentGrinForecast(),horizon=state.grinForecastHorizon??7;return `<section class="grin-forecast-panel" aria-label="GRIN后续时序预测"><div class="flex between wrap"><h3>GRIN补全 → 后续时序预测</h3>${chip('附加因果自回归预测头','purple')}</div><p class="description">以当前窗口截止日前的补全候选序列拟合预测头，再逐日递归预测。紫色虚线与三角标记表示未来值；不会把窗口内的补全值当作未来预测。</p><div class="grin-forecast-controls"><label for="grin-forecast-horizon">预测天数（天）</label><select id="grin-forecast-horizon">${[1,3,7,14,30].map(n=>`<option value="${n}" ${n===horizon?'selected':''}>未来 ${n} 天</option>`).join('')}</select>${btn('运行后续时序预测','run-grin-forecast',{primary:true,ic:'play'})}</div>${state.grinForecastError?`<div class="studio-error" role="alert">${esc(state.grinForecastError)}</div>`:''}${f?`<div class="forecast-summary" role="status"><b>已生成未来 ${f.horizon} 天预测</b><span>预测起点：${f.origin} → ${f.rows[0].date}；截止：${f.rows.at(-1).date}</span><span>历史样本：${view.rows.length}条；预测头拟合样本：${f.training_samples}组；拟合耗时：${num(f.training_seconds,4)} s（秒）</span></div><div class="table-scroll">${table(f.rows,[{key:'date',label:'未来日期'},{key:'step',label:'预测步长（天）',decimals:0},{key:'prediction',label:'未来预测值 · '+unit,render:v=>grinCell(v,v<0?'rejected':'forecast')},{key:'status',label:'质量标记',text:true}],{limit:f.rows.length})}</div><div class="compact-links section-gap">${btn('下载未来预测 CSV','export-grin-forecast',{ic:'download'})}${btn('下载预测参数与依据 JSON','export-grin-forecast-json',{ic:'download'})}</div>`:`<p class="description">运行后将延长上方时序图，并在此展示逐日未来预测值。尚未运行预测。</p>`}<details class="forecast-method"><summary>预测方法、公式与适用边界</summary><p>流程：多井观测与掩码 → 已训练GRIN窗口重建 → 当前井的完整候选序列 → 标准化 → 因果AR(3)岭回归头 → 未来逐日递归预测。</p><div class="math-equation" role="math">zₜ = (qₜ − μ) / σ；ẑₜ₊₁ = β₀ + Σⱼ₌₁³ βⱼ zₜ₊₁₋ⱼ<br>β* = argmin Σₜ(zₜ − β₀ − Σⱼ βⱼzₜ₋ⱼ)² + λΣⱼβⱼ²；λ = 10</div><p>q为当前变量，单位${unit}；z为无量纲标准化值；μ、σ只用当前窗口的历史候选数据计算；β是附加预测头的参数。这里只拟合附加预测头，不重新训练冻结GRIN。</p><p>这是14条历史记录上的短窗口研究基线，未来真实值尚未进入评估，不能据此报告预测准确率。负预测保留并标为待核查；不包含未来制度和措施变化。长预测期的不确定性更大。</p></details></section>`}
function runGrinForecast(){const view=getGrinView();state.qualityRun=true;state.qualityResult={...view,mode:'frozen_grin_completion',run_at:new Date().toISOString(),flagged:view.pending};state.grinForecastError='';state.grinForecast=null;try{const forecast=forecastCompletedSeries(view.rows,{horizon:state.grinForecastHorizon??7});state.grinForecast={...forecast,window_id:view.window_id,well_id:view.well_id,feature:view.feature};state.qualityResult.forecast=state.grinForecast;paint();notify(`已完成补全并生成未来${forecast.horizon}天时序预测。`)}catch(error){state.grinForecastError=error.message;paint();notify(error.message)}}
function exportGrinForecast(){const f=currentGrinForecast();if(!f)return notify('请先运行当前变量的后续时序预测');const unit=f.feature==='pressure_for_model_source_unit'?'源单位未核定':'标准立方米/日',lines=[['未来日期','预测步长（天）','预测值','变量','单位','质量标记','历史截止日','方法'],...f.rows.map(r=>[r.date,r.step,r.prediction,GRIN_FEATURE_LABELS[f.feature],unit,r.status,f.origin,'GRIN补全＋因果AR(3)岭回归预测头'])];download('\uFEFF'+lines.map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n'),'GRIN-future-forecast-'+f.window_id.replaceAll(':','_')+'.csv')}
function mountGrinChart(){const v=getGrinView(),f=currentGrinForecast(),n=v.rows.length,nh=f?.rows.length??0,pad=arr=>arr.concat(Array(nh).fill(null)),series=[{...GRIN_MARKS.observed,label:'原始观测',values:pad(v.input),fill:false,points:true}];if(state.qualityRun){series.push({...GRIN_MARKS.imputed,label:'GRIN补全候选',values:pad(v.rows.map(r=>r.filled?r.output_value:null)),line:false,fill:false,points:true},{...GRIN_MARKS.rejected,label:'拒绝接纳的预测',values:v.rows.map(r=>!r.filled&&r.input_value===null?r.prediction:null).concat(f?.rows.map(r=>r.prediction<0?r.prediction:null)??[]),line:false,fill:false,points:true},{...GRIN_MARKS.truth,label:'遮蔽评估真值',values:pad(v.target),line:false,fill:false,points:true});}if(f)series.push({...GRIN_MARKS.forecast,label:'未来时序预测',values:Array(n-1).fill(null).concat([v.output.at(-1),...f.rows.map(r=>r.prediction)]),fill:false,points:true,width:2.5});chart($('#grin-chart'),{labels:v.rows.map(r=>r.date).concat(f?.rows.map(r=>r.date)??[]),series,unit:v.feature==='pressure_for_model_source_unit'?'压力源单位未核定':'Sm3 / 日',height:310,missingIndices:v.rows.flatMap((r,i)=>r.input_value===null?[i]:[]),forecastStart:f?n:null})}
